python3 - <<'EOF'
p='packages/babel-traverse/src/scope/lib/renamer.ts'
s=open(p).read()
s=s.replace("""  Scope(path, state) {""","""  ObjectProperty: {
    exit({ node }) {
      if (!node.shorthand) return;
      let { value } = node;
      if (t.isAssignmentPattern(value)) value = value.left;
      if (
        t.isIdentifier(node.key) &&
        t.isIdentifier(value) &&
        node.key.name !== value.name
      ) {
        node.shorthand = false;
        if (node.extra?.shorthand) node.extra.shorthand = false;
      }
    },
  },

  Scope(path, state) {""",1)
open(p,'w').write(s)
